app_css:
.tool-app-liftledger { color: #1c1917; max-width: 960px; }
.tool-app-liftledger .ll-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; margin: 12px 0 16px; }
.tool-app-liftledger .ll-stat { background: #fffbeb; border: 1px solid #fde68a; border-radius: 12px; padding: 12px 14px; display: flex; flex-direction: column; }
.tool-app-liftledger .ll-stat-num { font-size: 26px; font-weight: 800; }
.tool-app-liftledger .ll-stat-label { font-size: 12px; color: #78716c; font-weight: 600; }
.tool-app-liftledger .ll-stat-bad { background: #fef2f2; border-color: #fecaca; }
.tool-app-liftledger .ll-stat-bad .ll-stat-num { color: #b91c1c; }
.tool-app-liftledger .ll-stat-warn .ll-stat-num { color: #b45309; }
.tool-app-liftledger .ll-formwrap { border: 1px solid #e7e5e4; border-radius: 12px; padding: 12px 14px; margin: 12px 0; background: #fafaf9; }
.tool-app-liftledger .ll-formwrap summary { cursor: pointer; font-size: 15px; }
.tool-app-liftledger .ll-form { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px; margin: 12px 0; }
.tool-app-liftledger .ll-form label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; }
.tool-app-liftledger .ll-form input, .tool-app-liftledger .ll-form select, .tool-app-liftledger .ll-toolbar input, .tool-app-liftledger .ll-toolbar select { border: 1px solid #d6d3d1; border-radius: 8px; padding: 8px 10px; font-size: 14px; }
.tool-app-liftledger .ll-btn { background: #B45309; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-liftledger .ll-btn:hover { background: #92400e; }
.tool-app-liftledger .ll-btn-ghost { background: #fef3c7; color: #92400e; padding: 8px 12px; }
.tool-app-liftledger .ll-btn-ghost:hover { background: #fde68a; }
.tool-app-liftledger .ll-btn-danger { background: #b91c1c; margin-top: 14px; }
.tool-app-liftledger .ll-toolbar { display: flex; gap: 8px; flex-wrap: wrap; margin: 14px 0; align-items: center; }
.tool-app-liftledger .ll-toolbar input { flex: 1 1 180px; }
.tool-app-liftledger .ll-table { width: 100%; border-collapse: collapse; margin: 8px 0; font-size: 14px; }
.tool-app-liftledger .ll-table th { text-align: left; font-size: 12px; color: #78716c; padding: 6px; border-bottom: 2px solid #e7e5e4; }
.tool-app-liftledger .ll-table td { padding: 8px 6px; border-bottom: 1px solid #f5f5f4; vertical-align: top; }
.tool-app-liftledger .ll-badge { display: inline-block; font-size: 12px; font-weight: 700; border-radius: 999px; padding: 3px 10px; white-space: nowrap; }
.tool-app-liftledger .ll-badge-overdue { background: #fee2e2; color: #991b1b; }
.tool-app-liftledger .ll-badge-due { background: #fef3c7; color: #92400e; }
.tool-app-liftledger .ll-badge-ok { background: #dcfce7; color: #166534; }
.tool-app-liftledger .ll-badge-na { background: #f5f5f4; color: #78716c; }
.tool-app-liftledger .ll-rowbtn { background: none; border: none; color: #B45309; font-weight: 700; cursor: pointer; font-size: 14px; padding: 0; }
.tool-app-liftledger .ll-empty { text-align: center; color: #78716c; padding: 22px; }
.tool-app-liftledger .ll-detail { border: 1px solid #e7e5e4; border-radius: 12px; padding: 16px; margin: 16px 0; background: #fffdf7; }
.tool-app-liftledger .ll-detail-head { display: flex; justify-content: space-between; align-items: center; }
.tool-app-liftledger .ll-detail-head h3 { margin: 0; }
.tool-app-liftledger .ll-detail-info { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 8px; margin: 10px 0; font-size: 14px; }
.tool-app-liftledger .ll-detail-info div { background: #fff; border: 1px solid #f5f5f4; border-radius: 8px; padding: 8px 10px; }
.tool-app-liftledger .ll-detail-info span { display: block; font-size: 11px; color: #78716c; font-weight: 600; }
.tool-app-liftledger .ll-detail h4 { margin: 14px 0 6px; }
.tool-app-liftledger .ll-history { list-style: none; padding: 0; margin: 8px 0; }
.tool-app-liftledger .ll-history li { background: #f5f5f4; border-radius: 8px; padding: 8px 12px; margin-bottom: 6px; font-size: 14px; display: flex; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
.tool-app-liftledger .ll-history .ll-hdate { font-weight: 700; }
.tool-app-liftledger .ll-note { font-size: 12px; color: #78716c; margin-top: 16px; }
.tool-app-liftledger .tool-print-doc { display: none; }
@media print {
  .tool-app-liftledger .ll-stats, .tool-app-liftledger .ll-formwrap, .tool-app-liftledger .ll-toolbar, .tool-app-liftledger .ll-detail, .tool-app-liftledger .ll-table, .tool-app-liftledger .ll-note { display: none !important; }
  .tool-app-liftledger .tool-print-doc { display: block !important; color: #000; }
  .tool-app-liftledger .tool-print-doc table { width: 100%; border-collapse: collapse; margin: 12px 0; }
  .tool-app-liftledger .tool-print-doc th, .tool-app-liftledger .tool-print-doc td { border: 1px solid #999; padding: 6px; text-align: left; font-size: 13px; }
}

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  var LS = 'toolapp-liftledger-units';
  var root = $('toolAppRoot');
  var selectedId = null;

  function parseISO(s) {
    var p = String(s).split('-');
    return new Date(Date.UTC(parseInt(p[0], 10), parseInt(p[1], 10) - 1, parseInt(p[2], 10)));
  }
  function isoOf(d) { return d.toISOString().slice(0, 10); }
  function todayISO() {
    var n = new Date();
    return isoOf(new Date(Date.UTC(n.getFullYear(), n.getMonth(), n.getDate())));
  }
  function addMonths(s, m) {
    var d = parseISO(s);
    d.setUTCMonth(d.getUTCMonth() + m);
    return isoOf(d);
  }
  function addDays(s, d) {
    var t = parseISO(s);
    t.setUTCDate(t.getUTCDate() + d);
    return isoOf(t);
  }
  function daysUntil(s) {
    return Math.round((parseISO(s).getTime() - parseISO(todayISO()).getTime()) / 864e5);
  }
  function fmt(s) {
    if (!s) return '--';
    return parseISO(s).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' });
  }

  function getUnits() {
    try { return JSON.parse(localStorage.getItem(LS)) || []; } catch (e) { return []; }
  }
  function setUnits(u) {
    try { localStorage.setItem(LS, JSON.stringify(u)); } catch (e) {}
  }
  function cycles(u) {
    var next1 = u.lastCat1 ? addMonths(u.lastCat1, 12) : (u.install ? addMonths(u.install, 12) : null);
    var next5 = u.lastCat5 ? addMonths(u.lastCat5, 60) : (u.install ? addMonths(u.install, 60) : null);
    return { next1: next1, next5: next5 };
  }
  function statusOf(u) {
    var c = cycles(u);
    if (!c.next1) return 'na';
    var d = daysUntil(c.next1);
    if (d < 0) return 'overdue';
    if (d <= 30) return 'due';
    return 'ok';
  }
  function statusBadge(st) {
    var map = { overdue: ['Overdue', 'll-badge-overdue'], due: ['Due in 30 days', 'll-badge-due'], ok: ['On track', 'll-badge-ok'], na: ['No date', 'll-badge-na'] };
    var m = map[st] || map.na;
    return '<span class="ll-badge ' + m[1] + '">' + m[0] + '</span>';
  }

  function seed() {
    var t = todayISO();
    function U(building, label, type, state, install, last1, last5) {
      return {
        id: 'u' + Math.random().toString(36).slice(2, 10),
        building: building, label: label, type: type, state: state,
        install: install, lastCat1: last1, lastCat5: last5,
        history: [
          { date: last1, kind: 'cat1', notes: 'Annual Category 1 test passed' },
          { date: last5, kind: 'cat5', notes: 'Full-load Category 5 test passed' }
        ]
      };
    }
    return [
      U('Grandview Tower', 'Car 1', 'Traction passenger', 'New York', addMonths(t, -72), addDays(addMonths(t, -12), -5), addMonths(t, -48)),
      U('Grandview Tower', 'Car 2', 'Traction passenger', 'New York', addMonths(t, -72), addDays(addMonths(t, -11), 0), addMonths(t, -36)),
      U('Meridian Plaza', 'North Bank', 'Hydraulic passenger', 'Texas', addMonths(t, -60), addMonths(t, -10), addMonths(t, -57)),
      U('Meridian Plaza', 'Freight', 'Freight', 'Texas', addMonths(t, -96), addDays(addMonths(t, -12), -40), addDays(addMonths(t, -60), -10)),
      U('City Court Hotel', 'Escalator 1', 'Escalator', 'Illinois', addMonths(t, -48), addMonths(t, -6), addMonths(t, -30)),
      U('City Court Hotel', 'Dumbwaiter', 'Dumbwaiter', 'Illinois', addMonths(t, -24), '', addMonths(t, -24))
    ];
  }

  function filtered() {
    var q = $('ll-filter-q').value.trim().toLowerCase();
    var st = $('ll-filter-status').value;
    return getUnits().filter(function (u) {
      if (st !== 'all' && statusOf(u) !== st) return false;
      if (q && (String(u.building) + ' ' + String(u.label)).toLowerCase().indexOf(q) === -1) return false;
      return true;
    }).sort(function (a, b) {
      var ca = cycles(a).next1, cb = cycles(b).next1;
      var da = ca ? daysUntil(ca) : 99999, db = cb ? daysUntil(cb) : 99999;
      return da - db;
    });
  }

  function render() {
    var units = getUnits();
    var overdue = 0, due30 = 0, cat5soon = 0;
    units.forEach(function (u) {
      var st = statusOf(u);
      if (st === 'overdue') overdue++;
      else if (st === 'due') due30++;
      var n5 = cycles(u).next5;
      if (n5) { var d = daysUntil(n5); if (d < 0 || d <= 90) cat5soon++; }
    });
    $('ll-stat-units').textContent = units.length;
    $('ll-stat-overdue').textContent = overdue;
    $('ll-stat-due30').textContent = due30;
    $('ll-stat-cat5').textContent = cat5soon;

    var rows = $('ll-rows');
    var list = filtered();
    if (!list.length) {
      rows.innerHTML = '<tr><td colspan="7" class="ll-empty">No units yet. Register your first unit above, or load the demo units.</td></tr>';
    } else {
      var html = '';
      list.forEach(function (u) {
        var c = cycles(u);
        var d1 = c.next1 ? daysUntil(c.next1) : null;
        var n1 = c.next1 ? fmt(c.next1) + ' (' + (d1 < 0 ? Math.abs(d1) + 'd overdue' : d1 + 'd') + ')' : '--';
        var n5 = c.next5 ? fmt(c.next5) : '--';
        html += '<tr>' +
          '<td><strong>' + esc(u.label) + '</strong></td>' +
          '<td>' + esc(u.building || '--') + '</td>' +
          '<td>' + esc(u.type) + '</td>' +
          '<td>' + n1 + '</td>' +
          '<td>' + n5 + '</td>' +
          '<td>' + statusBadge(statusOf(u)) + '</td>' +
          '<td><button type="button" class="ll-rowbtn" data-id="' + u.id + '">Open</button></td>' +
          '</tr>';
      });
      rows.innerHTML = html;
    }
    renderPrintDoc();
  }

  function renderDetail() {
    var u = getUnits().filter(function (x) { return x.id === selectedId; })[0];
    var box = $('ll-detail');
    if (!u) { box.hidden = true; return; }
    box.hidden = false;
    $('ll-detail-title').textContent = u.label + ' — ' + (u.building || 'No building');
    var c = cycles(u);
    function info(label, val) { return '<div><span>' + label + '</span>' + esc(val || '--') + '</div>'; }
    var kindNames = { cat1: 'Category 1 test', cat5: 'Category 5 test', other: 'Inspection' };
    $('ll-detail-info').innerHTML =
      info('Type', u.type) + info('State / AHJ', u.state) +
      info('Install date', fmt(u.install)) + info('Last Cat 1', fmt(u.lastCat1)) +
      info('Last Cat 5', fmt(u.lastCat5)) +
      info('Next Cat 1 due', c.next1 ? fmt(c.next1) : '--') +
      info('Next Cat 5 due', c.next5 ? fmt(c.next5) : '--') +
      info('Status', ({ overdue: 'Overdue', due: 'Due in 30 days', ok: 'On track', na: 'No date' })[statusOf(u)]);
    var hist = (u.history || []).slice().sort(function (a, b) { return a.date < b.date ? 1 : -1; });
    if (!hist.length) {
      $('ll-history').innerHTML = '<li>No tests logged yet.</li>';
    } else {
      $('ll-history').innerHTML = hist.map(function (h) {
        return '<li><span><span class="ll-hdate">' + fmt(h.date) + '</span> — ' + esc(kindNames[h.kind] || h.kind) +
          (h.notes ? ' <span style="color:#78716c">' + esc(h.notes) + '</span>' : '') + '</span></li>';
      }).join('');
    }
  }

  function renderPrintDoc() {
    var list = filtered();
    var rows = list.map(function (u) {
      var c = cycles(u);
      var st = { overdue: 'OVERDUE', due: 'Due in 30 days', ok: 'On track', na: 'No date' }[statusOf(u)];
      return '<tr><td>' + esc(u.label) + '</td><td>' + esc(u.building || '--') + '</td><td>' + esc(u.type) + '</td>' +
        '<td>' + fmt(c.next1) + '</td><td>' + fmt(c.next5) + '</td><td>' + st + '</td></tr>';
    }).join('');
    $('ll-printdoc').innerHTML = '<h1>LiftLedger — Test-cycle summary</h1><p>Generated ' + fmt(todayISO()) + '</p>' +
      '<table><thead><tr><th>Unit</th><th>Building</th><th>Type</th><th>Next Cat 1</th><th>Next Cat 5</th><th>Status</th></tr></thead>' +
      '<tbody>' + (rows || '<tr><td colspan="6">No units.</td></tr>') + '</tbody></table>';
  }

  function addUnit() {
    var label = $('ll-label').value.trim();
    if (!label) { alert('Give the unit a label, e.g. "Car 1".'); return; }
    var units = getUnits();
    units.push({
      id: 'u' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
      building: $('ll-building').value.trim(),
      label: label,
      type: $('ll-type').value,
      state: $('ll-state').value,
      install: $('ll-install').value,
      lastCat1: $('ll-lastcat1').value,
      lastCat5: $('ll-lastcat5').value,
      history: []
    });
    setUnits(units);
    ['ll-building', 'll-label', 'll-install', 'll-lastcat1', 'll-lastcat5'].forEach(function (id) { $(id).value = ''; });
    render();
  }

  function logTest() {
    var date = $('ll-testdate').value;
    if (!date) { alert('Pick the test date.'); return; }
    var units = getUnits();
    var u = units.filter(function (x) { return x.id === selectedId; })[0];
    if (!u) return;
    var kind = $('ll-testtype').value;
    var notes = $('ll-testnotes').value.trim();
    if (kind === 'cat1') u.lastCat1 = date;
    if (kind === 'cat5') { u.lastCat5 = date; u.lastCat1 = date; }
    u.history = u.history || [];
    u.history.push({ date: date, kind: kind, notes: notes });
    setUnits(units);
    $('ll-testdate').value = '';
    $('ll-testnotes').value = '';
    render();
    renderDetail();
  }

  function exportUnits() {
    var blob = new Blob([JSON.stringify(getUnits(), null, 2)], { type: 'application/json' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'liftledger-units.json';
    document.body.appendChild(a);
    a.click();
    setTimeout(function () { document.body.removeChild(a); URL.revokeObjectURL(a.href); }, 100);
  }

  function importUnits(file) {
    var reader = new FileReader();
    reader.onload = function () {
      try {
        var data = JSON.parse(reader.result);
        if (!Array.isArray(data)) throw new Error('not an array');
        data = data.filter(function (u) { return u && u.label; });
        setUnits(data);
        render();
        renderDetail();
      } catch (e) { alert('Could not import that file.'); }
    };
    reader.readAsText(file);
  }

  root.addEventListener('click', function (e) {
    var t = e.target;
    if (t.id === 'll-addunit') { addUnit(); return; }
    if (t.id === 'll-seed') {
      if (getUnits().length && !confirm('Replace your current units with the demo set?')) return;
      setUnits(seed());
      selectedId = null;
      render();
      renderDetail();
      return;
    }
    if (t.id === 'll-export') { exportUnits(); return; }
    if (t.id === 'll-importbtn') { $('ll-importfile').click(); return; }
    if (t.id === 'll-print') { renderPrintDoc(); window.print(); return; }
    if (t.id === 'll-logtest') { logTest(); return; }
    if (t.id === 'll-detail-close') { selectedId = null; renderDetail(); return; }
    if (t.id === 'll-delete') {
      if (!confirm('Delete this unit and its test history?')) return;
      setUnits(getUnits().filter(function (u) { return u.id !== selectedId; }));
      selectedId = null;
      render();
      renderDetail();
      return;
    }
    if (t.classList && t.classList.contains('ll-rowbtn')) {
      selectedId = t.getAttribute('data-id');
      $('ll-testdate').value = todayISO();
      renderDetail();
      $('ll-detail').scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  });
  root.addEventListener('input', function (e) {
    if (e.target.id === 'll-filter-q' || e.target.id === 'll-filter-status') render();
  });
  root.addEventListener('change', function (e) {
    if (e.target.id === 'll-importfile' && e.target.files.length) {
      importUnits(e.target.files[0]);
      e.target.value = '';
    }
  });

  render();
})();
